use kanpo_parser::{analyze_item,page_inputs};
fn compact(s:&str)->String{s.chars().filter(|c|!c.is_whitespace()).collect()}
#[test]fn actual_impact_20260812g001800015(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20260812g00180/20260812g001800015.pdf")).unwrap());let expected="額面金額×(3.7/100)×(１/２)";assert_eq!(compact(&a.text).matches(expected).count(),1,"{}",a.text);assert_eq!(a.articles.iter().filter(|art|compact(&art.text).contains(expected)&&compact(&doc_text(&art.document)).contains(expected)).count(),1);let owners:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter(|l|compact(&l.text).contains(expected)).collect();assert_eq!(owners.len(),1);assert_eq!(owners[0].words,vec![305, 285, 262, 253, 243, 213, 204, 193, 216, 196, 203, 202, 200, 192, 215, 214]);}
#[test]fn actual_impact_20260909g002010005(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20260909g00201/20260909g002010005.pdf")).unwrap());let expected="額面金額×(2.7/100)×(１/２)";assert_eq!(compact(&a.text).matches(expected).count(),1,"{}",a.text);assert_eq!(a.articles.iter().filter(|art|compact(&art.text).contains(expected)&&compact(&doc_text(&art.document)).contains(expected)).count(),1);let owners:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter(|l|compact(&l.text).contains(expected)).collect();assert_eq!(owners.len(),1);assert_eq!(owners[0].words,vec![151, 126, 112, 97, 80, 42, 25, 16, 45, 19, 24, 23, 21, 15, 44, 43]);}
#[test]fn actual_impact_20260909g002010011(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20260909g00201/20260909g002010011.pdf")).unwrap());let expected="額面金額×(1.56/100)×((１/２)−(２/365))";assert_eq!(compact(&a.text).matches(expected).count(),1,"{}",a.text);assert_eq!(a.articles.iter().filter(|art|compact(&art.text).contains(expected)&&compact(&doc_text(&art.document)).contains(expected)).count(),1);let owners:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter_map(|l|l.table.as_ref()).flat_map(|t|&t.cells).filter(|c|compact(&c.text).contains(expected)).collect();assert_eq!(owners.len(),1);assert_eq!(owners[0].words,vec![63, 64, 65, 29, 27, 26, 18, 13, 66, 23, 15, 28, 19, 14]);}
#[test]fn actual_impact_20260909g002010012(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20260909g00201/20260909g002010012.pdf")).unwrap());let expected="額面金額×(1.95/100)×((１/２)−(２/365))";assert_eq!(compact(&a.text).matches(expected).count(),1,"{}",a.text);assert_eq!(a.articles.iter().filter(|art|compact(&art.text).contains(expected)&&compact(&doc_text(&art.document)).contains(expected)).count(),1);let owners:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter(|l|compact(&l.text).contains(expected)).collect();assert_eq!(owners.len(),1);assert_eq!(owners[0].words,vec![141, 139, 138, 130, 125, 181, 135, 127, 140, 131, 126]);}

fn runs_text(rs:&[kanpo_parser::Run])->String {rs.iter().map(|r|{let mut s=r.text.clone();if let Some(t)=&r.table {for row in &t.rows{for c in row{s.push_str(&runs_text(c));}}}s}).collect()}
fn doc_text(d:&kanpo_parser::Document)->String {d.blocks.iter().map(|b|match b{kanpo_parser::Block::Paragraph{runs}=>runs_text(runs),kanpo_parser::Block::Shinkyu{rows}=>rows.iter().map(|r|{let mut s=runs_text(&r.after);s.push_str(&runs_text(&r.before));for t in [&r.after_table,&r.before_table].into_iter().flatten(){for row in &t.rows{for c in row{s.push_str(&runs_text(c));}}}s}).collect()}).collect()}
